  code = code.replace(/^export\s+function\s+([A-Za-z_$][\w$]*)/gm, (m, name) => {
    exported.push([name, name]);
    return `function ${name}`;
  });
  // export var foo = ...
  code = code.replace(/^export\s+var\s+([A-Za-z_$][\w$]*)/gm, (m, name) => {
    exported.push([name, name]);
    return `var ${name}`;
  });
  code += '\n' + exported.map(([exp, local]) => `exports.${exp} = ${local};`).join('\n') + '\n';
  return code;
}

function createLoader() {
  const cache = new Map();
  function load(filename) {
    const resolved = path.resolve(filename);
    if (cache.has(resolved)) return cache.get(resolved).exports;
    const mod = { exports: {} };
    cache.set(resolved, mod);
    const source = fs.readFileSync(resolved, 'utf8');
    const code = transform(source);
    const dir = path.dirname(resolved);
    const localRequire = (spec) => {
      if (!spec.startsWith('.')) return require(spec);
      const base = path.resolve(dir, spec);
      const candidates = [base, `${base}.js`, path.join(base, 'index.js')];
      const found = candidates.find((f) => fs.existsSync(f) && fs.statSync(f).isFile());
      if (!found) throw new Error(`Cannot find module '${spec}' from '${resolved}'`);
      return load(found);
    };
    const fn = new Function('exports', 'require', 'module', '__filename', '__dirname', code);
    fn(mod.exports, localRequire, mod, resolved, dir);
    return mod.exports;
  }
  return load;
}

module.exports = { createLoader, transform };
