const {createLoader} = require('/tmp/scratch/load.js');
const load = createLoader();
const zlib = require('zlib');
const m = load('/testbed/packages/imba/polyfills/zlib/zlib-lib/inflate.js');
const ZStream = load('/testbed/packages/imba/polyfills/zlib/zlib-lib/zstream.js').default;

function mk(wb) { const s = new ZStream(); const r = m.inflateInit2(s, wb); if (r !== 0) throw new Error('init'); return s; }
function setIn(s, buf, off) { s.input = new Uint8Array(buf); s.avail_in = buf.length; s.next_in = off || 0; }

const data = Buffer.from('abcdefghij'.repeat(100));
const comp = zlib.deflateSync(data);
for (const size of [1, 7, 8, 50, 1000]) {
  const s = mk(15);
  setIn(s, comp);
  const chunks = [];
  let ret = 0, guard = 0;
  while (ret !== 1 && guard++ < 20000) {
    const out = new Uint8Array(size);
    s.output = out; s.avail_out = size; s.next_out = 0;
    ret = m.inflate(s, 0);
    chunks.push(Buffer.from(out.subarray(0, size - s.avail_out)));
    if (ret < 0) break;
  }
  const res = Buffer.concat(chunks);
  console.log('size', size, 'ret', ret, 'guard', guard, 'equal', res.equals(data), 'total_out', s.total_out, 'msg', JSON.stringify(s.msg), 'datatype', s.data_type);
}

// Z_FINISH with exact-size output
{
  const s = mk(15);
  setIn(s, comp);
  const out = new Uint8Array(1000);
  s.output = out; s.avail_out = 1000; s.next_out = 0;
  const ret = m.inflate(s, 4);
  console.log('exact fit ret', ret, 'adler eq', s.adler, 'expect', comp.readInt32BE(comp.length-4), 'total_in', s.total_in, 'compLen', comp.length, 'dt', s.data_type, 'bits', s.state.bits);
}

// Z_BLOCK progressive
{
  const s = mk(15);
  setIn(s, comp);
  const out = new Uint8Array(1000);
  let ret = 0, n = 0;
  while (ret !== 1 && n++ < 100) {
    s.output = out; s.avail_out = 1000; s.next_out = 0;
    ret = m.inflate(s, 5);
    if (n < 5) console.log('block call', n, 'ret', ret, 'mode', s.state.mode, 'dt', s.data_type, 'avail_out', s.avail_out);
  }
  console.log('Z_BLOCK final', ret, 'calls', n);
}

// Z_TREES
{
  const s = mk(15);
  setIn(s, comp);
  const out = new Uint8Array(1000);
  const ret = m.inflate(s, 6);
  console.log('Z_TREES first ret', ret, 'mode', s.state.mode, 'dt', s.data_type, 'avail_in', s.avail_in, 'msg', JSON.stringify(s.msg));
  const ret2 = m.inflate(s, 6);
  console.log('Z_TREES second ret', ret2, 'mode', s.state.mode, 'dt', s.data_type, 'avail_in', s.avail_in);
}
EOF
