  });

  describe('with constructor parameters', () => {
    let result;
    let cls;
    let defaultValue;

    beforeEach(() => {
      // A class with an explicit constructor still gets a generated
      // "[__init__$]" method that owns the instance init block.
      result = compile('class A\n\tdef constructor()\n\t\tpass\n\ty = 2');
