    expect(result).toBe('');
  });

  test('indexes plain required parameters but emits no code', () => {
    const a = required('a');
    const b = required('b');

    const { list, result } = runHead(a, b);

    expect(list.nodes()).toEqual([a, b]);
    expect(result).toBe(nodes.EMPTY);
    expect(a.index()).toBe(0);
    expect(b.index()).toBe(1);
  });

  test('does not apply defaults to required parameters', () => {
