    const { result } = runHead(raw1, a, raw2, b);

    expect(result).toBe(
      'if(a === undefined) a = 1;\nif(b === undefined) b = 2;',
    );
    expect(raw1.index()).toBeUndefined();
    expect(a.index()).toBe(0);
    expect(raw2.index()).toBeUndefined();
    expect(b.index()).toBe(1);
  });

  test('defaults a single trailing optional parameter', () => {
    const { result } = runHead(optional('a', '1'));

    expect(result).toBe('if(a === undefined) a = 1;');

    const fn = new Function('a', result + '\nreturn a;');
    expect(fn(undefined)).toBe(1);
    expect(fn(0)).toBe(0);
    expect(fn(7)).toBe(7);
  });

  test('defaults multiple trailing optional parameters in order', () => {
    const { result } = runHead(optional('a', '1'), optional('b', '2'));

    expect(result).toBe(
      'if(a === undefined) a = 1;\nif(b === undefined) b = 2;',
    );

    const fn = new Function('a', 'b', result + '\nreturn [a, b];');
    expect(fn()).toEqual([1, 2]);
    expect(fn(7)).toEqual([7, 2]);
    expect(fn(7, 8)).toEqual([7, 8]);
  });

  test('defaults an optional parameter that follows required parameters', () => {
    const x = required('x');
    const a = optional('a', '1');

    const { result } = runHead(x, a);

    expect(result).toBe('if(a === undefined) a = 1;');
    expect(result).not.toContain('x');
    expect(x.index()).toBe(0);
    expect(a.index()).toBe(1);
  });

