      'if(blk==undefined && typeof a == \'function\') blk = a,a = 1;\n' +
        'if(a==undefined) a = 1;',
    );
    expect(result).not.toContain('x');
    expect(x.index()).toBe(0);
    expect(a.index()).toBe(1);
    expect(blk.index()).toBe(2);
  });

  test('extracts a trailing block from arguments when several optional parameters precede it', () => {
    const a = optional('a', '1');
    const b = optional('b', '2');
    const blk = block('blk');

    const { result } = runHead(a, b, blk);

    expect(result).toBe(
