    );
    const cb = () => {};
    expect(fn(cb)).toEqual({ a: 1, b: 2, blk: cb });
  });

  test('guards block extraction by argument length when required parameters precede it', () => {
    const x = required('x');
    const a = optional('a', '1');
    const b = optional('b', '2');
    const blk = block('blk');

    const { result } = runHead(x, a, b, blk);

    expect(result).toBe(
      'var $1 = arguments, $2 = $1.length;\n' +
        'var blk = $2 > 1 && typeof $1[$2-1] == \'function\' ? $1[--$2] : null;\n' +
        'if($2 < 2) a = 1;\n' +
        'if($2 < 3) b = 2;',
    );

    const fn = new Function(
      'var a, b, blk, x;\n' + result + '\nreturn { a: a, b: b, blk: blk };',
    );
    const cb = () => {};
    expect(fn(0, cb)).toEqual({ a: 1, b: 2, blk: cb });
  });

