    const named = new nodes.NamedParam(ident('opts'));
    const rest = new nodes.RestParam(ident('rest'));

    const { result } = runHead(named, rest);

    expect(result).toBe(nodes.EMPTY);
    expect(named.index()).toBe(0);
    expect(rest.index()).toBe(1);
  });

