    onTraversed(root, stack) {
      const classes = [];
      // walk root body to find ClassDeclaration nodes (top-level and nested)
      ...
      classes.sort by startLoc();
      for (const cls of classes) {
        outputs.push(SourceMapper.strip(cls.c()));
      }
    }
  });
  return outputs;
}
