/**
 * Unit tests for ClassDeclaration#js (implemented in
 * packages/imba/src/compiler/nodes.mjs).
 *
 * The method produces the JavaScript / TypeScript declaration for an Imba
 * class.  We parse real Imba source, let the compiler traverse it (which is
 * what wires up the class scope and mixins), and then invoke the class node's
 * code generation entry point (`.c()`, which calls `js()`) from the
 * `onTraversed` hook, while the compiler stack is still active.
 */

let compile;
let SourceMapper;

beforeAll(async () => {
  ({ compile } = await import('../../../../../../packages/imba/src/compiler/index.mjs'));
  ({ SourceMapper } = await import('../../../../../../packages/imba/src/compiler/sourcemapper.mjs'));
});

/** Walk the traversed AST and collect every ClassDeclaration in source order. */
function findClassDeclarations(root) {
  const seen = new Set();
  const found = [];
  const walk = (node) => {
    if (!node || typeof node !== 'object' || seen.has(node)) return;
    seen.add(node);
    if (node.constructor && node.constructor.name === 'ClassDeclaration') {
      found.push(node);
    }
    if (Array.isArray(node)) {
      node.forEach(walk);
      return;
    }
    for (const key of [
      '_nodes',
      '_body',
      '_left',
      '_right',
      '_statements',
      '_items',
      '_expression',
      '_value',
    ]) {
      if (key in node) walk(node[key]);
    }
  };
  walk(root.body ? root.body() : root._body);
  found.sort((a, b) => {
    const la = a.startLoc();
    const lb = b.startLoc();
    return la < lb ? -1 : la > lb ? 1 : 0;
  });
  return found;
}

/**
 * Compile `code` and return the rendered output of every top-level class
 * declaration.  Source-map markers are stripped so assertions can target the
 * actual emitted code, including in `platform: 'tsc'` mode.
 */
function renderClasses(code, options = {}) {
  let classes = [];
  let outputs = [];
  compile(code, {
    ...options,
    sourcePath: 'test.imba',
    onTraversed(root) {
      classes = findClassDeclarations(root);
      outputs = classes.map((cls) => SourceMapper.strip(String(cls.c())));
    },
  });
  return { classes, outputs };
}

describe('ClassDeclaration.js - plain JavaScript output', () => {
  test('emits a named class declaration containing its body', () => {
    const { outputs } = renderClasses('class Foo\n\tx = 1');

    expect(outputs).toHaveLength(1);
    expect(outputs[0]).toMatch(/^class Foo \{/);
    expect(outputs[0]).toContain('this.x = ');
    expect(outputs[0].endsWith('}')).toBe(true);
  });

  test('emits an anonymous class when no name is supplied', () => {
    const { outputs } = renderClasses('x = class\n\ty = 1');

    expect(outputs).toHaveLength(1);
    expect(outputs[0]).toMatch(/^class \{/);
    expect(outputs[0]).not.toMatch(/^class \w+ \{/);
  });

  test('includes a superclass with `extends`', () => {
    const { outputs } = renderClasses(
      'class Bar\n\tx = 1\nclass Foo < Bar\n\ty = 2',
    );

    expect(outputs).toHaveLength(2);
    expect(outputs[1]).toMatch(/^class Foo extends Bar \{/);
  });

  test('uses multi$ with a single mixin relation', () => {
    const { outputs } = renderClasses(
      'mixin M\n\tm = 1\nclass Foo\n\tof M\n\tx = 1',
    );

    expect(outputs).toHaveLength(2);
    expect(outputs[1]).toMatch(/^class Foo extends multi\$\(c\$0,null,M\) \{/);
  });

  test('combines the superclass and all mixins in-order', () => {
    const { outputs } = renderClasses(
      'mixin A\n\ta = 1\nmixin B\n\tb = 2\nclass Foo\n\tof A\n\tof B\n\tx = 1',
    );

    expect(outputs).toHaveLength(3);
    expect(outputs[2]).toMatch(
      /^class Foo extends multi\$\(c\$0,null,A,B\) \{/,
    );
  });

  test('assigns namespaced class names to their access path', () => {
    const { outputs } = renderClasses('class Foo.Bar\n\tx = 1');

    expect(outputs).toHaveLength(1);
    expect(outputs[0]).toMatch(/^Foo\.Bar = class Bar \{/);
  });

  test('prefixes exported classes with `export`', () => {
    const { outputs } = renderClasses('export class Foo\n\tx = 1');

    expect(outputs).toHaveLength(1);
    expect(outputs[0]).toMatch(/^export class Foo \{/);
    expect(outputs[0]).not.toContain('export default');
  });

  test('prefixes default exports with `export default`', () => {
    const { outputs } = renderClasses('export default class Foo\n\tx = 1');

    expect(outputs).toHaveLength(1);
    expect(outputs[0]).toMatch(/^export default class Foo \{/);
  });

  test('appends a global assignment for global classes', () => {
    const { outputs } = renderClasses('global class Foo\n\tx = 1');

    expect(outputs).toHaveLength(1);
    expect(outputs[0]).toMatch(/^class Foo \{/);
    expect(outputs[0]).toMatch(/\}; globalThis\.Foo = Foo$/);
  });

  test('uses the namespaced accessor for global namespaced classes', () => {
    const { outputs } = renderClasses('global class Foo.Bar\n\tx = 1');

    expect(outputs).toHaveLength(1);
    expect(outputs[0]).toMatch(/^Foo\.Bar = class Bar \{/);
    expect(outputs[0].endsWith('; globalThis.Bar = Foo.Bar')).toBe(true);
  });

  test('supports export and global on the same class', () => {
    const { outputs } = renderClasses('export global class Foo\n\tx = 1');

    expect(outputs).toHaveLength(1);
    expect(outputs[0]).toMatch(/^export class Foo \{/);
    expect(outputs[0]).toMatch(/\}; globalThis\.Foo = Foo$/);
  });

  test('renders an empty body without instance initializers', () => {
    const { outputs } = renderClasses('class Foo');

    expect(outputs).toHaveLength(1);
    expect(outputs[0]).toBe(
      "class Foo {\nstatic { register$(this,c$0,'Foo',0) }}",
    );
    expect(outputs[0]).not.toContain('constructor');
  });

  test('sets the class scope context value and reference to its name', () => {
    const { classes } = renderClasses('class Foo\n\tx = 1');

    expect(classes).toHaveLength(1);
    const cls = classes[0];
    const context = cls.scope().context();

    expect(context._value).toBe(cls.name());
    expect(context._reference).toBe(cls.name());
  });
});

describe('ClassDeclaration.js - TypeScript output (platform: tsc)', () => {
  test('emits generic class declarations', () => {
    const { outputs } = renderClasses('class Foo<T>\n\tx = 1', {
      platform: 'tsc',
    });

    expect(outputs).toHaveLength(1);
    expect(outputs[0]).toBe('class Foo<T> {\n\tx = 1\n\n}');
  });

  test('supports default exports', () => {
    const { outputs } = renderClasses('export default class Foo\n\tx = 1', {
      platform: 'tsc',
    });

    expect(outputs).toHaveLength(1);
    expect(outputs[0]).toMatch(/^export default class Foo \{/);
  });

  test('emits an interface declaration for declared interfaces', () => {
    const { outputs } = renderClasses('declare interface Foo\n\tx = 1', {
      platform: 'tsc',
    });

    expect(outputs).toHaveLength(1);
    expect(outputs[0]).toMatch(/^interface Foo \{/);
    expect(outputs[0]).not.toMatch(/class Foo/);
