    const { outputs } = renderClasses('global class Foo\n\tx = 1', {
      platform: 'tsc',
    });

    expect(outputs).toHaveLength(1);
    expect(outputs[0]).toContain('namespace Global {');
    expect(outputs[0]).toContain('declare const Foo$: unique symbol;');
    expect(outputs[0]).toContain('ImbaSubclassUnion');
