    const { outputs } = renderClasses('export global class Foo\n\tx = 1', {
      platform: 'tsc',
    });

    expect(outputs).toHaveLength(1);
    expect(outputs[0]).toMatch(/^namespace Global \{/);
    expect(outputs[0]).toContain('\nexport import Foo = Global.Foo; \n');
