/**
 * Unit tests for ClassDeclaration#js (implemented in
 * packages/imba/src/compiler/nodes.mjs).
 *
 * The method produces the JavaScript / TypeScript declaration for an Imba
 * class.  We parse real Imba source, let the compiler traverse it (which is
 * what wires up the class scope and mixins), and then invoke the class node's
 * code generation entry point (`.c()`, which calls `js()`) from the
 * `onTraversed` hook, while the compiler stack is still active.
 */

let compile;
let SourceMapper;

beforeAll(async () => {
  ({ compile } = await import('../../../../../../packages/imba/src/compiler/index.mjs'));
  ({ SourceMapper } = await import('../../../../../../packages/imba/src/compiler/sourcemapper.mjs'));
});

/** Walk the traversed AST and collect every ClassDeclaration in source order. */
function findClassDeclarations(root) {
  const seen = new Set();
  const found = [];
  const walk = (node) => {
    if (!node || typeof node !== 'object' || seen.has(node)) return;
    seen.add(node);
    if (node.constructor && node.constructor.name === 'ClassDeclaration') {
      found.push(node);
    }
    if (Array.isArray(node)) {
      node.forEach(walk);
      return;
    }
    for (const key of [
      '_nodes',
      '_body',
      '_left',
      '_right',
      '_statements',
      '_items',
...
  });

  test('renders an empty body without whitespace-only output', () => {
    const { outputs } = renderClasses('class Foo', { platform: 'tsc' });

    expect(outputs).toHaveLength(1);
    expect(outputs[0]).toBe('class Foo {\n}');
  });

  test('emits classes nested in functions', () => {
    const { outputs } = renderClasses(
      'def make\n\tclass Bar\n\t\tx = 1\n\tBar',
      { platform: 'tsc' },
    );

    expect(outputs).toHaveLength(1);
    expect(outputs[0]).toMatch(/^class Bar \{/);
    expect(outputs[0]).toContain('x = 1');
  });
});

