{"command": "cat > test/packages/imba/src/compiler/nodes/js.test.js <<'EOF'
const COMPILER_INDEX = '../../../../../../packages/imba/src/compiler/index.mjs';
const COMPILER_MODULE = '../../../../../../packages/imba/src/compiler/compiler.mjs';
const COMPILATION_MODULE = '../../../../../../packages/imba/src/compiler/compilation.mjs';
const NODES_MODULE = '../../../../../../packages/imba/src/compiler/nodes.mjs';

let loadPromise;
let compile;
let Compilation;
let AmperFunc;

async function loadCompiler() {
  if (!loadPromise) {
    loadPromise = (async () => {
      // Importing the compiler module installs the parser/lexer hooks used by
      // Compilation when we construct one directly in the focused branch tests.
      const index = await import(COMPILER_INDEX);
      await import(COMPILER_MODULE);
      const compilation = await import(COMPILATION_MODULE);
      const nodes = await import(NODES_MODULE);

      compile = index.compile;
      Compilation = compilation.Compilation;
      AmperFunc = nodes.AmperFunc;
    })();
  }
  return loadPromise;
}

async function compileSource(source, options = {}) {
  await loadCompiler();
  return compile(source, {
    sourcePath: 'amper-test.imba',
    platform: 'browser',
    ...options,
  });
}

async function compileWithHook(source, onTraversed) {
  await loadCompiler();
  const compilation = new Compilation(source, {
    sourcePath: 'amper-test.imba',
    platform: 'browser',
    onTraversed,
  });
  return compilation.compile();
}

function warningMessages(result) {
  return (result.warnings || []).map((warning) => warning.message);
}

function findAmperFuncs(root) {
  const found = [];
  const seen = new Set();
  const nonAstContainers = new Set([
    'Variable',
    'VariableDeclarator',
    'RootScope',
    'BlockScope',
    'MethodScope',
    'LambdaScope',
    'ScopeContext',
    'RootScopeContext',
  ]);

  function walk(value) {
    if (!value || typeof value !== 'object' || seen.has(value)) return;
    seen.add(value);

    if (value instanceof AmperFunc) found.push(value);

    const constructorName = value.constructor && value.constructor.name;
    if (nonAstContainers.has(constructorName)) return;

    for (const key of Object.keys(value)) {
      if (
        key === '_scope' ||
        key === '_options' ||
        key === '_token' ||
        key === '_variable'
      ) {
        continue;
      }

      const child = value[key];
      if (Array.isArray(child)) {
        for (const item of child) walk(item);
      } else if (child && typeof child === 'object') {
        walk(child);
      }
    }
  }

  walk(root.body());
  return found;
}

function onlyAmper(root) {
  const ampers = findAmperFuncs(root);
  if (ampers.length !== 1) {
    throw new Error(`Expected exactly one AmperFunc, found ${ampers.length}`);
  }
  return ampers[0];
}

describe('AmperFunc.js memoization analysis', () => {
  test('emits a plain arrow without memoization in TypeScript mode', async () => {
    const result = await compileSource(
      'let x = 1\nlet f = arr.map(&.id == x)\n',
      { platform: 'tsc' },
    );

    expect(result.js).toContain('arr.map(((v$)=>v$.id == x))');
    expect(result.js).not.toContain('memofunc');
    expect(warningMessages(result)).toEqual([]);
  });

  test('hoists a capture-free amperfunction as a shared global memofunc', async () => {
    const result = await compileSource('let f = arr.map(&.id)\n');

    const declaration = result.js.match(
      /var (ƒ\d+) = imba_memofunc\("&\.id",globalThis,\(v\$\)=>v\$\.id\);/,
    );
    expect(declaration).not.toBeNull();
    expect(result.js).toContain(`let f = arr.map(${declaration[1]});`);
    expect(warningMessages(result)).toEqual([]);
  });

  test('reuses one hoisted definition for identical capture-free source', async () => {
    const result = await compileSource(
      'let a = [1].map(&.id)\nlet b = [2].map(&.id)\n',
    );

    const declarations =
      result.js.match(/var ƒ\d+ = imba_memofunc\("&\.id",/g) || [];
    expect(declarations).toHaveLength(1);

    const declaration = result.js.match(/var (ƒ\d+) = imba_memofunc/);
    expect(declaration).not.toBeNull();
    expect(result.js.split(`.map(${declaration[1]})`)).toHaveLength(3);
  });

  test('normalizes double quotes in the memoization key but not in code', async () => {
    const result = await compileSource(
      'let f = arr.map(&.label == "hello")\n',
    );

    expect(result.js).toContain(
      'imba_memofunc("&.label == \'hello\'",globalThis,(v$)=>v$.label == "hello")',
    );
  });

  test('memoizes explicit self references per instance', async () => {
    const result = await compileSource(
      'class A\n\tdef m\n\t\tarr.map(&.owner == self.owner)\n',
    );

    expect(result.js).toContain(
      'imba_memofunc("&.owner == self.owner",this,(v$)=>v$.owner == this.owner)',
    );
    expect(result.js).not.toContain('var ƒ');
  });

  test('treats implicit self access as an instance-bound reference', async () => {
    const result = await compileSource(
      'class A\n\tdef m\n\t\tarr.map(&.owner == owner)\n',
    );

    expect(result.js).toContain(
      'imba_memofunc("&.owner == owner",this,(v$)=>v$.owner == this.owner)',
    );
    expect(result.js).not.toContain('var ƒ');
  });

  test('uses the capture-slot helper for a single effectively-final capture', async () => {
    const result = await compileSource(
