{"command": "cd /testbed; cat > 'test/packages/imba/src/compiler/nodes/js.test.js' <<'EOF'
/**
 * Unit tests for `Access#js` in packages/imba/src/compiler/nodes.mjs.
 *
 * `Access#js` is the code generator for member access expressions
 * (`obj.prop`, `obj[expr]`, `obj?.prop`, ...). It is exercised through the
 * public `Node#c()` entry point, which pushes the access node on the compiler
 * stack and then delegates to `js`. A real (but empty) `Root` is compiled once
 * so the stack has a root scope: helper generation (`negIndex$__`) and symbol
 * identifiers need one.
 */
import {
  Access,
  Assign,
  Block,
  Identifier,
  ImplicitAccess,
  Index,
  InterpolatedIdentifier,
  Num,
  Root,
  Self,
  Str,
  STACK,
  Symbol as SymbolNode,
  SymbolIdentifier,
  VarAccess,
} from '../../../../../../packages/imba/src/compiler/nodes.mjs';
import { Token } from '../../../../../../packages/imba/src/compiler/token.mjs';

let rootScope;

beforeAll(() => {
  const root = new Root([], {});
  root.compile({ sourcePath: 'test/access-js.imba' }, { sourceCode: '' });
  rootScope = STACK.root();
});

beforeEach(() => {
  // The compiler stack is a module level singleton; reset it so every test
  // starts from a clean state without compiler options such as `tsc`.
  STACK.reset();
});

/** Compile `access` while the root scope of a real compilation is active. */
function generate(access) {
  let out;
  STACK.withScope(rootScope, () => {
    out = access.c();
  });
  return out;
}

function dot(left, right, op = '.') {
  return generate(new Access(op, left, right));
}

describe('Access#js - identifier like members', () => {
  test('compiles an identifier member as a dot access', () => {
    expect(dot(new Identifier('user'), new Identifier('name'))).toBe(
      'user.name',
    );
  });

  test('compiles a string member that is a valid identifier as a dot access', () => {
    expect(dot(new Identifier('user'), new Str("'name'"))).toBe('user.name');
  });

  test('compiles predeclared looking string members as a dot access', () => {
    expect(dot(new Identifier('user'), new Str("'class'"))).toBe('user.class');
    expect(dot(new Identifier('user'), new Str("'_private'"))).toBe(
      'user._private',
    );
    expect(dot(new Identifier('user'), new Str("'$el'"))).toBe('user.$el');
  });

  test('compiles a valid identifier symbol member as a dot access', () => {
    expect(dot(new Identifier('user'), new SymbolNode(':name'))).toBe(
      'user.name',
    );
  });

  test('wraps a raw token member into an identifier access', () => {
    expect(dot(new Identifier('user'), new Token(2, 'name', 5))).toBe(
      'user.name',
    );
  });
});

describe('Access#js - members that need brackets', () => {
  test('brackets string members that are not valid identifiers', () => {
    expect(dot(new Identifier('user'), new Str("'first-name'"))).toBe(
      "user['first-name']",
    );
    expect(dot(new Identifier('user'), new Str("'first name'"))).toBe(
      "user['first name']",
    );
    expect(dot(new Identifier('user'), new Str("'0abc'"))).toBe("user['0abc']");
    expect(dot(new Identifier('user'), new Str('"he said"'))).toBe(
      'user["he said"]',
    );
  });

  test('brackets symbol members that are not valid identifiers', () => {
    expect(dot(new Identifier('user'), new SymbolNode(':0abc'))).toBe(
      "user['0abc']",
    );
  });

  test('brackets the value of an interpolated identifier', () => {
    expect(
      dot(new Identifier('user'), new InterpolatedIdentifier(new Identifier('key'))),
    ).toBe("user['key']");
  });

  test('brackets a non node member by its string representation', () => {
    expect(dot(new Identifier('user'), 'someRawExpr')).toBe('user[someRawExpr]');
  });

  test('brackets symbol identifiers through the root symbol table', () => {
    expect(dot(new Identifier('user'), new SymbolIdentifier('Ωflag'))).toBe(
      'user[Ωflag$]',
    );
  });
});

describe('Access#js - numeric members', () => {
  test('brackets a numeric member', () => {
    expect(dot(new Identifier('user'), new Num('2'))).toBe('user[2]');
    expect(dot(new Identifier('user'), new Num('0'))).toBe('user[0]');
    expect(dot(new Identifier('user'), new Num('10_000'))).toBe('user[10000]');
  });

  test('unwraps an index node around a number', () => {
    expect(dot(new Identifier('user'), new Index(new Num('2')))).toBe(
      'user[2]',
    );
  });

  test('unwraps an index node around a string', () => {
    expect(dot(new Identifier('user'), new Index(new Str('"name"')))).toBe(
      'user.name',
    );
  });

  test('unwraps an index node around a symbol', () => {
    expect(dot(new Identifier('user'), new Index(new SymbolNode(':name')))).toBe(
      'user.name',
    );
  });

  test('compiles a negative index through the negIndex helper', () => {
    expect(dot(new Num('2'), new Num('-1'))).toBe('negIndex$__(2,-1)');
    expect(dot(new Num('items'), new Index(new Num('-3')))).toBe(
      'negIndex$__(\'items\',-3)',
    );
  });
});

describe('Access#js - safe chaining', () => {
  test('reports safechain only for the ?. operator', () => {
    expect(new Access('.', new Identifier('a'), new Identifier('b')).safechain()).toBe(false);
    expect(new Access('?.', new Identifier('a'), new Identifier('b')).safechain()).toBe(true);
  });

  test('prefixes dot accesses with ?. for safe chains', () => {
    expect(dot(new Identifier('user'), new Identifier('name'), '?.')).toBe(
      'user?.name',
    );
    expect(dot(new Identifier('user'), new Str("'name'"), '?.')).toBe(
      'user?.name',
    );
  });

  test('prefixes bracket accesses with ?. for safe chains', () => {
    expect(dot(new Identifier('user'), new Num('2'), '?.')).toBe('user?.[2]');
    expect(dot(new Identifier('user'), 'expr', '?.')).toBe('user?.[expr]');
  });

  test('uses the optional negIndex helper for safe negative indexes', () => {
    expect(dot(new Num('2'), new Num('-1'), '?.')).toBe('optNegIndex$__(2,-1)');
  });
});

describe('Access#js - left hand side handling', () => {
  test('falls back to the scope context when there is no left side', () => {
    expect(dot(null, new Identifier('name'))).toBe('globalThis.name');
  });

  test('compiles self as the scope context', () => {
    expect(dot(new Self(), new Identifier('x'))).toBe('globalThis.x');
  });

  test('parenthesizes a number used as the context of a dot access', () => {
    expect(dot(new Num('2'), new Identifier('b'))).toBe('(2).b');
  });

  test('keeps a string context as is', () => {
    expect(dot(new Str("'abc'"), new Identifier('length'))).toBe(
      "'abc'.length",
    );
  });

  test('remembers the starting location of the left or right operand', () => {
    const left = new Num('2');
    left._startLoc = 4;
    const access = new Access('.', left, new Identifier('b'));
    generate(access);
    expect(access._startLoc).toBe(4);
  });

  test('keeps an explicit starting location', () => {
    const left = new Num('2');
    left._startLoc = 4;
    const access = new Access('.', left, new Identifier('b'));
    access._startLoc = 42;
    generate(access);
    expect(access._startLoc).toBe(42);
  });
});

describe('Access#js - implicit access', () => {
  test('compiles an implicit access like a regular access', () => {
    const out = generate(
      new ImplicitAccess('.', new Identifier('user'), new Identifier('name')),
    );
    expect(String(out)).toBe('user.name');
  });
});

describe('Access#js - import proxies', () => {
  test('delegates the access to the import proxy of the left side', () => {
    const proxy = rootScope.importProxy('fs');
    const left = new VarAccess(new Identifier('fs'));
    left._variable = proxy;
    expect(generate(new Access('.', left, new Identifier('readFileSync')))).toBe(
      'fs.readFileSync',
    );
  });
});

describe('Access#js - typescript output', () => {
  test('compiles plain accesses unchanged when the tsc option is set', () => {
    STACK.option('tsc', true);
    expect(dot(new Identifier('user'), new Identifier('name'))).toBe(
      'user.name',
    );
  });

  test('does not use the negIndex helper when the tsc option is set', () => {
    STACK.option('tsc', true);
    expect(dot(new Identifier('items'), new Num('-3'))).toBe('items[-3]');
  });

  test('guards predicate accesses with an "in" check', () => {
    STACK.option('tsc', true);
    expect(dot(new Identifier('user'), new Identifier('active?'))).toBe(
      "('activeΦ' in user && user.activeΦ)",
    );
  });

  test('adds a function check for called predicate accesses', () => {
    STACK.option('tsc', true);
    const access = new Access('.', new Identifier('user'), new Identifier('active?'));
    access._call = true;
    expect(generate(access)).toBe(
      "('activeΦ' in user && user.activeΦ instanceof Function && user.activeΦ)",
    );
  });

  test('compiles assigned predicate accesses through the context', () => {
    STACK.option('tsc', true);
    const access = new Access('.', new Identifier('user'), new Identifier('active?'));
    access._assigns = true;
    expect(generate(access)).toBe("('activeΦ' in user && user).activeΦ");
  });

  test('skips the predicate guard when the context is self', () => {
    STACK.option('tsc', true);
    expect(dot(new Self(), new Identifier('active?'))).toBe(
      'globalThis.activeΦ',
    );
  });

  test('guards safe chain accesses with an "in" check', () => {
    STACK.option('tsc', true);
    expect(dot(new Identifier('user'), new Identifier('name'), '?.')).toBe(
      "(('name' in user) && user?.name)",
    );
  });

  test('adds a function check for called safe chain accesses', () => {
    STACK.option('tsc', true);
    const access = new Access('?.', new Identifier('user'), new Identifier('name'));
    access._call = true;
    expect(generate(access)).toBe(
      "(('name' in user) && user?.name instanceof Function && user.name)",
    );
  });

  test('appends the datatype of the access', () => {
    STACK.option('tsc', true);
    const access = new Access('.', new Identifier('user'), new Identifier('name'));
    access.option('datatype', new Identifier('string'));
    expect(generate(access)).toBe('user.name as string');
  });

  test('appends the datatype when the access is the right side of an assign', () => {
    STACK.option('tsc', true);
    const access = new Access('.', new Identifier('user'), new Identifier('name'));
    access.option('datatype', new Identifier('number'));
    const assignment = new Assign('=', new Identifier('copy'), access);
    STACK.push(assignment);
    let out;
    try {
      out = access.c();
    } finally {
      STACK.pop(assignment);
    }
    expect(out).toBe('user.name as number');
  });

  test('does not append the datatype when the access is not the assigned value', () => {
    STACK.option('tsc', true);
    const access = new Access('.', new Identifier('user'), new Identifier('name'));
    access.option('datatype', new Identifier('number'));
    const assignment = new Assign('=', new Identifier('copy'), new Identifier('other'));
    STACK.push(assignment);
    let out;
    try {
      out = access.c();
    } finally {
      STACK.pop(assignment);
    }
    expect(out).toBe('user.name');
  });
});
