{"command": "cd /testbed; cat > /testbed/tmp_probe2.mjs <<'EOF'
import { compile } from './packages/imba/src/compiler/compiler.mjs';
const cases = {
  autoTitle: `<div title>`,
  selectValue: `<select value="x">`,
  textareaValue: `<textarea value="x">`,
  buttonValue: `<button value="x">`,
  bindVar: `let x = 1
<div bind:value=x>`,
  bindArr: `let a = 1
let b = 2
<div bind:value=[a,b]>`,
  bindOther: `<div bind:foo=bar>`,
  htmlValue: `<div html:value="x">`,
  htmlData: `<div html:data-x=1>`,
  styleVar: `<div style="color:red">`,
  ariaDynamic: `let x = "a"
<div aria-label=x>`,
  customNoVal: `<div --foo>`,
};
for (const [name, src] of Object.entries(cases)) {
  for (const platform of ['web','node','tsc']) {
    try {
      const out = compile(src, {platform, format:'esm', sourcePath:'/tmp/file.imba'});
      const diag = (out.diagnostics||[]).map(d=>d.message);
      const js=(out.js||'').trim();
      console.log('####', name, platform, 'universal=', out.universal, 'diag=', JSON.stringify(diag));
      console.log(js.split('\n').filter(l=>/τT|setAttribute|set\$|css\$|bind\$|richValue|\.src|use_dom_bind/.test(l)).join('\n'));
    } catch(e){ console.log('ERR', name, platform, e.message); }
  }
}
EOF
node /testbed/tmp_probe2.mjs > /testbed/probe2.out 2>&1; wc -l /testbed/probe2.out; sed -n '1,120p' /testbed/probe2.out"}

