"use strict";

// Unit tests for TagContent#js() in packages/imba/src/compiler/nodes.mjs.
//
// TagContent#js() lowers a single tag child into JavaScript source. The method
// delegates the final rendering of the wrapped value (`value.c`), variable
// naming, symbol lookup, and DOM calls to collaborators. Those collaborators
// require a fully traversed compiler stack, so here they are replaced with
// deterministic stubs while the branching logic under test remains untouched.

let N;

const NODES_PATH = "../../../../../../packages/imba/src/compiler/nodes.mjs";

beforeAll(async () => {
  N = await import(NODES_PATH);
});

let savedTsc;
let savedPlatform;

beforeEach(() => {
  savedTsc = N.STACK._options.tsc;
  savedPlatform = N.STACK._options.platform;
});

afterEach(() => {
  if (savedTsc === undefined) {
    delete N.STACK._options.tsc;
  } else {
    N.STACK._options.tsc = savedTsc;
  }
  if (savedPlatform === undefined) {
    delete N.STACK._options.platform;
  } else {
    N.STACK._options.platform = savedPlatform;
  }
});

function onlyChildFlags() {
  return N.F.TAG_FIRST_CHILD | N.F.TAG_LAST_CHILD;
}

/** A non-special TagLike parent that is neither a Tag nor a switch fragment. */
function makePlainParent(cvar = "PC") {
  const parent = new N.TagFragment({});
  parent.cvar = jest.fn(() => cvar);
  return parent;
}

function makeTagParent(opts = {}) {
  const parent = new N.Tag({});
  if (opts.slot) parent._kind = "slot";
  parent.cvar = jest.fn(() => opts.cvar || "PC");
  return parent;
}

function makeSwitchParent(cvar = "PC") {
  const parent = new N.TagSwitchFragment({});
  parent.cvar = jest.fn(() => cvar);
  return parent;
}

/**
 * Build a TagContent whose compiler collaborators are deterministic.
 * The real `value()`/`isStatic()`/`isDetached()`/`isOnlyChild()` logic is
 * kept because it participates in the branches under test.
 */
function makeContent(value, opts = {}) {
  const content = new N.TagContent({
    value,
    detached: !!opts.detached,
  });

  content._parent = opts.parent || makePlainParent(opts.cvar);
  content._flags = opts.flags === undefined ? 0 : opts.flags;
  if (opts.tvar !== undefined) content._tvar = opts.tvar;
  content._o = opts.o;

  content.runtime = () => ({ renderContext: "CTX" });
  content.domCall = (name) => "[dom:" + name + "]";
  content.osym = (ns = "") => "sym" + ns;
  content.bvar = () => "BB";
  content.ref = () => "RR";
  content.vvar = () => "VV";
  content.key = () => "KK";
  content.fragment = () => ({ tvar: () => "FF" });

  return content;
}

function str(value = '"hi"') {
  return new N.Str(value);
}

function num(value = 7) {
  return new N.Num(value);
}

function text(content = "TEXT") {
  const node = new N.TagTextContent("x");
  node.c = jest.fn(() => content);
  return node;
}

function call(content = "CALLEE()") {
  const node = new N.Call();
  node.c = jest.fn(() => content);
  return node;
}

function bangCall(content = "BANG()") {
  const node = new N.BangCall();
  node.c = jest.fn(() => content);
  return node;
}

function plain(content = "VAL") {
  return { c: jest.fn(() => content) };
}

describe("TagContent#js in tsc mode", () => {
  test("returns the value compiled directly when STACK.tsc() is true", () => {
    N.STACK._options.tsc = true;
    const value = plain("CUSTOM");

    const content = makeContent(value);

    expect(content.js()).toBe("CUSTOM");
  });

  test("forwards the compilation options `_o` to value.c", () => {
    N.STACK._options.tsc = true;
    const value = plain("CUSTOM");
    const options = { mark: false };
    const content = makeContent(value, { o: options });

    expect(content.js()).toBe("CUSTOM");
    expect(value.c).toHaveBeenCalledTimes(1);
    expect(value.c).toHaveBeenCalledWith(options);
  });

  test("treats a tsc platform as tsc mode", () => {
    N.STACK._options.platform = "tsc";
    const value = plain("PLATFORM");

    expect(makeContent(value).js()).toBe("PLATFORM");
  });
});

describe("TagContent#js for switch-fragment parents", () => {
  test("assigns the branch tvar for a static string", () => {
    const content = makeContent(str('"hi"'), {
      parent: makeSwitchParent(),
      tvar: "TV",
    });

    expect(content.js()).toBe('(TV="hi")');
  });

  test("wraps a Call in render-context setup and teardown", () => {
    const parent = makeSwitchParent("PC");
    const value = call("CALLEE()");
    const content = makeContent(value, { parent, tvar: "TV" });

    expect(content.js()).toBe(
      "(CTX.context=(PC[sym$] || (PC[sym$]={_:FF})),TV=CALLEE(),CTX.context=null)",
    );
  });

  test("wraps a BangCall in render-context setup and teardown", () => {
    const parent = makeSwitchParent("PC");
    const value = bangCall("BANG()");
    const content = makeContent(value, { parent, tvar: "TV" });

    expect(content.js()).toBe(
      "(CTX.context=(PC[sym$] || (PC[sym$]={_:FF})),TV=BANG(),CTX.context=null)",
    );
  });

  test("forwards `_o` to value.c in a switch fragment", () => {
    const value = str('"hi"');
    value.c = jest.fn(() => '"HI"');
    const options = { sourcemap: true };
    const content = makeContent(value, {
      parent: makeSwitchParent(),
      tvar: "TV",
      o: options,
    });

    expect(content.js()).toBe('(TV="HI")');
    expect(value.c).toHaveBeenCalledWith(options);
  });
});

describe("TagContent#js for detached/slot tag parents", () => {
  test("assigns the tvar when the parent Tag is a slot and `_tvar` exists", () => {
    const content = makeContent(plain("VAL"), {
      parent: makeTagParent({ slot: true }),
      tvar: "TV",
    });

    expect(content.js()).toBe("(TV=VAL)");
  });

  test("assigns the tvar when the content is detached and `_tvar` exists", () => {
    const content = makeContent(plain("VAL"), {
      parent: makeTagParent(),
      tvar: "TV",
      detached: true,
    });

    expect(content.js()).toBe("(TV=VAL)");
  });

  test("does not take the tag-parent branch when `_tvar` is missing", () => {
    // A slot parent alone is not enough: `_tvar` must be truthy.
    const value = str('"hi"');
    const content = makeContent(value, {
      parent: makeTagParent({ slot: true }),
      flags: 0,
    });

    expect(content.js()).toBe('BB || RR[dom:insert]("hi")');
  });

  test("does not take the tag-parent branch when detached but `_tvar` is missing", () => {
    const value = str('"hi"');
    const content = makeContent(value, {
      parent: makeTagParent(),
      detached: true,
      flags: 0,
    });

    expect(content.js()).toBe('BB || RR[dom:insert]("hi")');
  });

  test("requires the parent to be a Tag (not just any TagLike)", () => {
    const content = makeContent(str('"hi"'), {
      parent: makePlainParent(),
      tvar: "TV",
      flags: onlyChildFlags(),
    });

    // Falls through to the static only-child text assignment.
    expect(content.js()).toBe('BB || RR.text$("hi")');
  });
});

describe("TagContent#js for only-child static text", () => {
  test("uses text$ for a Str only child", () => {
    const content = makeContent(str('"hi"'), { flags: onlyChildFlags() });

    expect(content.js()).toBe('BB || RR.text$("hi")');
  });

  test("uses text$ for a Num only child", () => {
    const content = makeContent(num(42), { flags: onlyChildFlags() });

    expect(content.js()).toBe("BB || RR.text$(42)");
  });

  test("forwards `_o` to the value compiler", () => {
    const value = str('"hi"');
    value.c = jest.fn(() => '"HI"');
    const options = { expression: true };
    const content = makeContent(value, {
      flags: onlyChildFlags(),
      o: options,
    });

    expect(content.js()).toBe('BB || RR.text$("HI")');
    expect(value.c).toHaveBeenCalledWith(options);
  });
});

describe("TagContent#js for static values that are not only children", () => {
  test("inserts a Str through the DOM insert symbol", () => {
    const content = makeContent(str('"hi"'), { flags: 0 });

    expect(content.js()).toBe('BB || RR[dom:insert]("hi")');
  });

  test("inserts a Num through the DOM insert symbol", () => {
    const content = makeContent(num(42), { flags: 0 });

    expect(content.js()).toBe("BB || RR[dom:insert](42)");
  });

  test("a first-but-not-last child is not treated as an only child", () => {
    const content = makeContent(str('"hi"'), {
      flags: N.F.TAG_FIRST_CHILD,
    });

    expect(content.isOnlyChild()).toBeFalsy();
    expect(content.js()).toBe('BB || RR[dom:insert]("hi")');
  });

  test("a last-but-not-first child is not treated as an only child", () => {
    const content = makeContent(str('"hi"'), {
      flags: N.F.TAG_LAST_CHILD,
    });

    expect(content.isOnlyChild()).toBeFalsy();
    expect(content.js()).toBe('BB || RR[dom:insert]("hi")');
  });
});

describe("TagContent#js for TagTextContent", () => {
  test("updates text$ when it is the only child of a non-switch parent", () => {
    const value = text("TEXT");
    const content = makeContent(value, { flags: onlyChildFlags() });

    expect(content.js()).toBe("(VV=TEXT,VV===KK || RR.text$(String(KK=VV)))");
    expect(value.c).toHaveBeenCalled();
  });

  test("a switch-fragment parent takes precedence over the only-child text path", () => {
    const value = text("TEXT");
    const content = makeContent(value, {
      parent: makeSwitchParent(),
      tvar: "TV",
      flags: onlyChildFlags(),
    });

    expect(content.js()).toBe("(TV=TEXT)");
  });

  test("a non-only TagTextContent is inserted with String(key=value)", () => {
    const value = text("TEXT");
    const content = makeContent(value, { flags: 5 });

    expect(content.js()).toBe(
      "(VV=TEXT,(VV===KK&&BB) || (PC[symi] = RR[dom:insert](String(KK=VV),5,PC[symi])))",
    );
  });
});

describe("TagContent#js generic insertion path", () => {
  test("inserts an arbitrary dynamic value and guards it with the key", () => {
    const value = plain("VAL");
    const content = makeContent(value, { flags: 5 });

    expect(content.js()).toBe(
      "(VV=VAL,(VV===KK&&BB) || (PC[symi] = RR[dom:insert](KK=VV,5,PC[symi])))",
    );
  });

  test("forwards `_o` to an arbitrary value compiler", () => {
    const value = plain("VAL");
    const options = { cache: true };
    const content = makeContent(value, { flags: 5, o: options });

    expect(content.js()).toBe(
      "(VV=VAL,(VV===KK&&BB) || (PC[symi] = RR[dom:insert](KK=VV,5,PC[symi])))",
    );
    expect(value.c).toHaveBeenCalledWith(options);
  });

  test("wraps a Call into render-context setup/teardown before insertion", () => {
    const value = call("CALLEE()");
    const content = makeContent(value, { flags: 0 });

    expect(content.js()).toBe(
      "(CTX.context=(PC[sym$] || (PC[sym$]={_:FF})),VV=CALLEE(),CTX.context=null,(VV===KK&&BB) || (PC[symi] = RR[dom:insert](KK=VV,0,PC[symi])))",
    );
  });

  test("wraps a BangCall into render-context setup/teardown before insertion", () => {
    const value = bangCall("BANG()");
    const content = makeContent(value, { flags: 0 });

    expect(content.js()).toBe(
      "(CTX.context=(PC[sym$] || (PC[sym$]={_:FF})),VV=BANG(),CTX.context=null,(VV===KK&&BB) || (PC[symi] = RR[dom:insert](KK=VV,0,PC[symi])))",
    );
  });

  test("uses the parent cvar and osym namespaces for lookups", () => {
    const parent = makePlainParent("PARENT");
    const content = makeContent(call("CALLEE()"), { parent, flags: 0 });

    const output = content.js();
    expect(output).toContain("PARENT[sym$]");
    expect(output).toContain("PARENT[symi]");
  });
});

