const path = require('path');

const ROOT = path.resolve(__dirname, '../../../../../..');

let rewrite;
let selparser;

beforeAll(async () => {
  const [selparseModule, parserModule] = await Promise.all([
    import(path.join(ROOT, 'packages/imba/src/compiler/selparse.mjs')),
    import(path.join(ROOT, 'packages/imba/vendor/css-selector-parser.mjs')),
  ]);
  rewrite = selparseModule.rewrite;
  selparser = parserModule;
});

function parse(selector) {
  return selparser.parse(selector);
}

function run(selector, options = {}) {
  return rewrite(parse(selector), null, options);
}

function collectParts(ruleSet) {
  const parts = [];
  let part = ruleSet.rule;
  while (part) {
    parts.push(part);
    part = part.rule;
  }
  return parts;
}

function lastPart(ruleSet) {
  return collectParts(ruleSet).at(-1);
}

function makeScope(ns = 'ns-abc', id = 'id-abc') {
  return {
    cssns: () => ns,
    cssid: () => id,
  };
}

describe('rewrite', () => {
  describe('non ruleSet input', () => {
    test('returns a non-ruleSet object unchanged', () => {
      const value = { type: 'rule', tagName: 'div', custom: 1 };
      const result = rewrite(value, null, {});
      expect(result).toBe(value);
      expect(value).toEqual({ type: 'rule', tagName: 'div', custom: 1 });
    });

    test('rewrites every selector in a selectors wrapper and returns it unchanged', () => {
      const rule = parse('.a, .b');
      const result = rewrite(rule, null, {});

      expect(result).toBe(rule);
      expect(rule.type).toBe('selectors');
      expect(rule.selectors).toHaveLength(2);
      for (const selector of rule.selectors) {
        expect(selector.type).toBe('ruleSet');
        expect(selector.meta).toEqual({});
        expect(selector.scopeTo).toBeNull();
        expect(selector.media).toEqual([]);
        expect(selector.container).toEqual([]);
        expect(selector.rule.s1).toBe(0);
        expect(selector.rule.s2).toBe(1);
      }
    });

    test('passes the selectors wrapper as context to transition selectors', () => {
      const rule = parse('.a@in, .b@out');
      const result = rewrite(rule, null, {});

      expect(result).toBe(rule);
      expect(rule.hasTransitionStyles).toBe(true);
      expect(rule._in_).toBe(true);
      expect(rule._out_).toBe(true);
      expect(rule.selectors.map((selector) => selector.rule.s1)).toEqual([4, 4]);
    });
  });

  describe('ruleSet normalisation', () => {
    test('resets ruleSet metadata while preserving unrelated properties', () => {
      const rule = parse('.foo');
      rule.meta = { stale: true };
      rule.scopeTo = '.stale';
      rule.media = ['(stale: 1)'];
      rule.container = ['stale-container'];
      rule.custom = 'keep-me';

      rewrite(rule, null, {});

      expect(rule.meta).toEqual({});
      expect(rule.scopeTo).toBeNull();
      expect(rule.media).toEqual([]);
      expect(rule.container).toEqual([]);
      expect(rule.custom).toBe('keep-me');
    });

    test('marks ordinary selectors as scoped', () => {
      const rule = run('.foo');
      const part = rule.rule;

      expect(part.isScoped).toBe(true);
      expect(part.op).toBeUndefined();
      expect(part.s1).toBe(0);
      expect(part.s2).toBe(1);
    });

    test('does not mark body or html selectors as scoped', () => {
      const body = run('body');
      expect(body.rule.tagName).toBe('body');
      expect(body.rule.isScoped).toBe(false);

      const html = run('html');
      expect(html.rule.tagName).toBe('html');
      expect(html.rule.isScoped).toBe(false);
      expect(html.rule.isRoot).toBe(true);
    });

    test('marks html and :root selectors as root selectors', () => {
      const tag = run('html');
      expect(tag.rule.isRoot).toBe(true);

      const pseudo = run('div:root');
      expect(pseudo.rule.isRoot).toBe(true);
      expect(pseudo.rule[0].pseudo).toBe('root');

      const modifier = run('div@root');
      expect(modifier.rule.isRoot).toBe(true);
    });

    test('turns self into a scope part without a tag name', () => {
      const rule = run('self');
      const part = rule.rule;

      expect(part.isScope).toBe(true);
      expect(part.isScoped).toBe(false);
      expect(part.tagName).toBeNull();
    });

    test('turns self in a descendant selector into the outer scope', () => {
      const rule = run('self .foo');
      const outer = rule.rule;
      const inner = outer.rule;

      expect(outer.isScope).toBe(true);
      expect(outer.isScoped).toBe(false);
      expect(outer.tagName).toBeNull();
      expect(inner.isScoped).toBe(true);
      expect(inner[0].flag).toBe('foo');
    });

    test('injects a deep scope part for a leading universal selector', () => {
      const rule = run('* .foo');
      const scope = rule.rule;

      expect(scope.isScope).toBe(true);
      expect(scope.isScoped).toBe(false);
      expect(scope.tagName).toBeNull();
      expect(scope.nestingOperator).toBeNull();
      expect(scope.op).toBe('>>>');
      expect(scope.rule).toBeDefined();
      expect(scope.rule[0].flag).toBe('foo');
    });

    test('injects a scope part for a bare universal selector', () => {
      const rule = run('*');
      const scope = rule.rule;

      expect(scope.isScope).toBe(true);
      expect(scope.nestingOperator).toBeNull();
      expect(scope.op).toBe('>>>');
      expect(scope.rule.tagName).toBe('*');
    });

    test('recognises an implicit scope part', () => {
      const rule = run('..foo');
      const part = rule.rule;

      expect(part.implicitScope).toBe(true);
      expect(part.isScope).toBe(true);
      expect(part.isScoped).toBe(false);
      expect(part.s2).toBe(0);
    });
  });

  describe('up references', () => {
    test('moves an item marked with up to the next shallower part', () => {
      const rule = run('.foo .bar .baz^.qux');
      const foo = rule.rule;
      const bar = foo.rule;
      const baz = bar.rule;

      expect(bar[1].flag).toBe('qux');
      expect(bar[1].up).toBe(0);
      expect(baz[0].flag).toBe('baz');
      expect(baz[1]).toEqual({});
    });
  });

  describe('deep combinators', () => {
    test('translates >> into a child combinator and records the original operator', () => {
      const rule = run('.foo >> .bar');
      const outer = rule.rule;
      const inner = outer.rule;

      expect(outer.isScoped).toBe(true);
      expect(inner.op).toBe('>>');
      expect(inner.nestingOperator).toBe('>');
      expect(inner.isScoped).toBeUndefined();
      expect(inner.s2).toBe(1);
    });

    test('translates >>> into an unscoped deep combinator', () => {
      const rule = run('.foo >>> .bar');
      const outer = rule.rule;

    const outer = rule.rule;
    const inner = outer.rule;

    expect(outer.isScoped).toBe(true);
    expect(inner.op).toBe('>>>');
    expect(inner.nestingOperator).toBeNull();
    expect(inner.isScoped).toBeUndefined();
  });

  test('leaves ordinary child combinators scoped', () => {
    const rule = run('.foo > .bar');
    const outer = rule.rule;
    const inner = outer.rule;

    expect(outer.isScoped).toBe(true);
    expect(inner.op).toBe('>');
    expect(inner.nestingOperator).toBe('>');
    expect(inner.isScoped).toBe(true);
  });
});

describe('modifier translation', () => {
  test('adds named media modifiers to the item and the ruleSet', () => {
    const rule = run('div@md');

    expect(rule.rule[0].media).toBe('(min-width: 768px)');
    expect(rule.media).toEqual(['(min-width: 768px)']);
  });

  test('collects multiple media modifiers in order', () => {
    const rule = run('div@md@lg');

    expect(rule.media).toEqual(['(min-width: 768px)', '(min-width: 1024px)']);
    expect(rule.rule[0].media).toBe('(min-width: 768px)');
    expect(rule.rule[1].media).toBe('(min-width: 1024px)');
  });

  test('uses the negative media variant for negated named modifiers', () => {
    const rule = run('div@!md');

    expect(rule.rule[0].not).toBe(true);
    expect(rule.rule[0].media).toBe('(max-width: 767px)');
    expect(rule.media).toEqual(['(max-width: 767px)']);
  });

  test('uses the negative media variant for named theme modifiers', () => {
    const rule = run('div@!dark');

    expect(rule.rule[0].media).toBe('(prefers-color-scheme: light)');
    expect(rule.media).toEqual(['(prefers-color-scheme: light)']);
  });

  test('derives min and max width media queries from numeric modifiers', () => {
    const min = run('div@480');
    expect(min.rule[0].media).toBe('(min-width: 480px)');
    expect(min.media).toEqual(['(min-width: 480px)']);

    const negated = run('div@!480h');
    expect(negated.rule[0].media).toBe('(max-height: 479px)');
    expect(negated.media).toEqual(['(max-height: 479px)']);
  });

  test('recognises the width and height suffixes on numeric modifiers', () => {
    expect(run('div@120w').rule[0].media).toBe('(min-width: 120px)');
    expect(run('div@120h').rule[0].media).toBe('(min-height: 120px)');
    expect(run('div@0').rule[0].media).toBe('(min-width: 0px)');
    expect(run('div@!0').rule[0].media).toBe('(max-width: -1px)');
  });

  test('wraps an explicit media modifier value in parentheses', () => {
    const rule = run('div@media(min-width: 10px)');

    expect(rule.rule[0].media).toBe('(min-width: 10px)');
    expect(rule.media).toEqual(['(min-width: 10px)']);
  });

  test('uses a container query for scroll state modifiers', () => {
    const rule = run('div@scrollable');

    expect(rule.rule[0].container).toBe('scroll-state(scrollable: top)');
    expect(rule.container).toEqual(['scroll-state(scrollable: top)']);
    expect(rule.media).toEqual([]);
  });

  test('maps directional scroll state modifiers to container queries', () => {
    const rule = run('div@scrollable-top');

    expect(rule.container).toEqual(['scroll-state(scrollable: top)']);
  });

  test('uses the container branch for numeric modifiers on closest selectors', () => {
    const rule = run('..foo@480');

    expect(rule.media).toEqual([]);
    expect(rule.container).toEqual(['(min-width: 480px)']);
    expect(rule.rule[1].container).toBe('(min-width: 480px)');
    expect(rule.rule[1].media).toBeUndefined();
  });

  test('uses the negated container branch for negated numeric closest modifiers', () => {
    const rule = run('..foo@!480h');

    expect(rule.media).toEqual([]);
    expect(rule.container).toEqual(['(max-height: 479px)']);
    expect(rule.rule[1].container).toBe('(max-height: 479px)');
  });

  test('expands odd and even into nth-child selectors', () => {
    const odd = run('div@odd');
    expect(odd.rule[0]).toMatchObject({ name: 'nth-child', value: 'odd', valueType: 'string' });

    const even = run('div@even');
    expect(even.rule[0]).toMatchObject({ name: 'nth-child', value: 'even', valueType: 'string' });
  });

  test('marks important modifiers and increases specificity', () => {
    const rule = run('div@important');
    const item = rule.rule[0];

    expect(item.pseudo).toBeNull();
    expect(item.important).toBe(true);
    expect(rule.rule.s1).toBe(1);
    expect(rule.rule.s2).toBe(1);
  });

  test('force behaves like important', () => {
    const rule = run('div@force');

    expect(rule.rule[0].pseudo).toBeNull();
    expect(rule.rule[0].important).toBe(true);
    expect(rule.rule.s1).toBe(1);
  });

  test('adds a class for local modifiers when namespacing is active', () => {
    const options = { ns: 'ns-x' };
    const rule = run('div@local', options);

    expect(rule.rule[0].flag).toBe('ns-x');
    expect(rule.rule[1].pseudo).toBe('local');
    expect(rule.rule[1].remove).toBe(true);
    expect(options.hasScopedStyles).toBe(true);
  });

  test('records scoped modifiers through the supplied scope', () => {
    const rule = run('.foo@scoped', { scope: makeScope('ns-abc', 'id-abc') });

    expect(rule.scopeTo).toBe('.id-abc');
    expect(rule.rule[0]).toEqual({ pseudo: 'scope' });
    expect(rule.rule.type).toBe('rule');
    expect(rule.rule.rule).toBeUndefined();
    expect(rule.scopeFrom).toHaveLength(1);
    expect(rule.scopeFrom[0].some((item) => item.name === '@scoped' && item.pseudo === null)).toBe(true);
  });

  test('falls back to an undefined scope id when cssid is unavailable', () => {
    const rule = run('.foo@scoped', { scope: { cssns: () => 'ns-abc' } });

    expect(rule.scopeTo).toBe('.undefined');
    expect(rule.rule[0]).toEqual({ pseudo: 'scope' });
  });

  test('records scope-to modifiers through their value', () => {
    const rule = run('.foo@scope-to(bar)');

    expect(rule.scopeTo).toBe('bar');
    expect(rule.rule[0]).toEqual({ pseudo: 'scope' });
    expect(rule.rule.type).toBe('rule');
    expect(rule.scopeFrom).toHaveLength(1);
    const item = rule.scopeFrom[0].find((entry) => entry.name === '@scope-to');
    expect(item.pseudo).toBeNull();
    expect(item.scopeTo).toBe('bar');
  });
});

describe('transition states', () => {
  test.each(['in', 'out', 'off'])('marks @%s rules as transition styles', (state) => {
    const rule = run('div@' + state);

    expect(rule.hasTransitionStyles).toBe(true);
    expect(rule['_' + state + '_']).toBe(true);
    expect(rule.rule.s1).toBe(4);
  });

  test('stores transition flags on the supplied context instead of the ruleSet', () => {
    const rule = parse('div@in');
    const context = {};

    const result = rewrite(rule, context, {});

    expect(result).toBe(rule);
    expect(context.hasTransitionStyles).toBe(true);
    expect(context._in_).toBe(true);
    expect(rule.hasTransitionStyles).toBeUndefined();
    expect(rule._in_).toBeUndefined();
    expect(rule.rule.s1).toBe(4);
  });

  test('combines off-state specificity with important modifiers', () => {
    const rule = run('div@in@important');

    expect(rule.rule.s1).toBe(5);
    expect(rule.rule[1].important).toBe(true);
  });
});

describe('scope classes', () => {
  test('adds the namespace class to a scoped selector', () => {
    const cssns = jest.fn(() => 'ns-abc');
    const cssid = jest.fn(() => 'id-abc');
    const rule = run('.foo', { scope: { cssns, cssid } });
    const part = rule.rule;

    expect(part[0].flag).toBe('ns-abc');
    expect(part.metas).toEqual(['ns-abc']);
    expect(part.s2).toBe(0);
    expect(cssns).toHaveBeenCalledTimes(1);
    expect(cssid).not.toHaveBeenCalled();
  });

  test('adds namespace classes to every scoped part', () => {
    const rule = run('.foo .bar', { scope: makeScope() });
    const outer = rule.rule;
    const inner = outer.rule;

    expect(outer[0].flag).toBe('ns-abc');
    expect(outer.metas).toEqual(['ns-abc']);
    expect(inner[0].flag).toBe('ns-abc');
    expect(inner.metas).toEqual(['ns-abc']);
  });

  test('uses the css id for an injected universal scope', () => {
    const cssns = jest.fn(() => 'ns-abc');
    const cssid = jest.fn(() => 'id-abc');
    const rule = run('* .foo', { scope: { cssns, cssid } });

    expect(rule.rule[0].flag).toBe('id-abc');
    expect(rule.rule.metas).toEqual(['id-abc']);
    expect(cssid).toHaveBeenCalledTimes(1);
    expect(cssns).not.toHaveBeenCalled();
  });

  test('falls back to the namespace when an injected scope has no css id', () => {
    const rule = run('* .foo', { scope: { cssns: () => 'only-ns' } });

    expect(rule.rule[0].flag).toBe('only-ns');
    expect(rule.rule.metas).toEqual(['only-ns']);
  });

  test('uses an explicit id when injecting a scope for an unconfined selector', () => {
    const cssns = jest.fn(() => 'ns-abc');
    const cssid = jest.fn(() => 'id-abc');
    const rule = run('.foo', { id: 'myid', scope: { cssns, cssid } });
    const scope = rule.rule;

    expect(scope.isScope).toBe(true);
    expect(scope[0].flag).toBe('myid');
    expect(scope.metas).toEqual(['myid']);
    expect(scope.rule.metas).toEqual(['ns-abc']);
    expect(cssid).not.toHaveBeenCalled();
    expect(cssns).toHaveBeenCalledTimes(1);
  });
});

